// ──── Fetch available models ────

/** Catalog base URLs that shipped with a never-workable wire path in earlier
 *  releases, mapped to the corrected shape. Saved providers still carrying
 *  one of these exact strings are patched once on load — every string here
 *  404s on every request (or is still an unfilled "{placeholder}" template),
 *  so rewriting it cannot clobber a working customization. */
const LEGACY_CATALOG_BASES: Record<string, { apiBase: string; wirePath?: string; apiFormat?: "openai" | "anthropic" }> = {
	"https://bedrock-runtime.{region}.amazonaws.com":
		{ apiBase: "https://bedrock-runtime.{region}.amazonaws.com/openai" },
	"https://generativelanguage.googleapis.com/v1beta":
		{ apiBase: "https://generativelanguage.googleapis.com/v1beta/openai", wirePath: "/chat/completions" },
	"https://{region}-aiplatform.googleapis.com/v1beta":
		{ apiBase: "https://{region}-aiplatform.googleapis.com/v1/projects/{project}/locations/{region}/endpoints/openai",
			wirePath: "/chat/completions" },
	// Z.AI Coding CN: the Anthropic-wire host from the Claude Code docs
	// (…/api/anthropic) never answers CORS preflight, so it only works from
	// non-browser clients — in-app it must use the OpenAI-wire coding route
	// (preflight verified live). Saved providers on the anthropic base
	// migrate across; old coding-base entries get the wire path filled in.
	"https://api.z.ai/api/coding/paas/v4": { apiBase: "https://api.z.ai/api/coding/paas/v4", wirePath: "/chat/completions" },
	"https://open.bigmodel.cn/api/anthropic": { apiBase: "https://open.bigmodel.cn/api/coding/paas/v4", wirePath: "/chat/completions", apiFormat: "openai" },
	"https://open.bigmodel.cn/api/coding/paas/v4": { apiBase: "https://open.bigmodel.cn/api/coding/paas/v4", wirePath: "/chat/completions" },
	// Cloudflare AI Gateway: the unified compat route carries no "/v1" segment
	// after the gateway slug — saved catalog providers 404 without wirePath.
	"https://gateway.ai.cloudflare.com/v1/{account_id}/{gateway_slug}":
		{ apiBase: "https://gateway.ai.cloudflare.com/v1/{account_id}/{gateway_slug}", wirePath: "/compat/chat/completions" },
};

/** Apply the legacy catalog base fixes to the saved provider list. */
export function migrateLegacyCatalogBases(settings: SmartVaultSettings): void {
	for (const p of settings.providers ?? []) {
		const fix = LEGACY_CATALOG_BASES[p.apiBase.trim().replace(/\/+$/, "")];
		if (!fix) continue;
		p.apiBase = fix.apiBase;
		if (fix.wirePath !== undefined) {
			p.wirePath = fix.wirePath;
		} else if (fix.apiFormat) {
			// Format switch (e.g. OpenAI → Anthropic wire): the old wire-path
			// override points at the dead route and cannot survive the move.
			p.wirePath = undefined;
		}
		if (fix.apiFormat) p.apiFormat = fix.apiFormat;
	}
}

/** Model kinds. Cost-conscious classification: rerank (and known embedding
 *  ids) come from keywords with zero requests; everything else is probed
 *  against the embedding endpoint only — a model that fails it is "unknown".
 *  Chat/speech/image/video/translation models are deliberately NOT probed or
 *  tagged, since a per-model chat probe is the expensive part. */
export type ModelKind = "embedding" | "chat" | "rerank" | "tts" | "asr" | "image" | "video" | "translate" | "unknown";

export interface FetchedModel {
	id: string;
	kind: ModelKind;
	/** Context window reported by the endpoint itself, when it carries one
	 *  (non-standard but common, e.g. OpenRouter's `context_length`). */
	contextWindow?: number;
}

/**
 * Keyword classification — zero network requests. Only rerank (and known
 * embedding ids) is unambiguous enough to tag from the id alone; speech,
 * image, video and translation models are deliberately left "unknown" (they
 * are not worth a per-model probe).
 */
function classifyById(modelId: string): ModelKind | null {
	const id = modelId.toLowerCase();
	if (/rerank/.test(id)) return "rerank";
	if (/(^|[^a-z])(bge|e5|gte)([^a-z]|$)|embedding|text-embedding/.test(id)) return "embedding";
	return null;
}

/** Response fields providers use to report a model's context window. The
 *  OpenAI-compatible `GET /models` spec only guarantees `id`, so these are
 *  best-effort grabs of the common spellings. */
const CONTEXT_FIELDS = [
	"context_length",
	"contextWindow",
	"context_window",
	"max_context_length",
	"max_input_tokens",
] as const;

/** Read a model entry's context window from the response, if present. */
function contextOf(entry: unknown): number | undefined {
	if (typeof entry !== "object" || entry === null) return undefined;
	const obj = entry as Record<string, unknown>;
	for (const field of CONTEXT_FIELDS) {
		const v = obj[field];
		if (typeof v === "number" && v > 0) return Math.floor(v);
		if (typeof v === "string") {
			const n = parseInt(v, 10);
			if (!isNaN(n) && n > 0) return n;
		}
	}
	return undefined;
}

/** Probe order: chat first (most models are chat, early exit), then
 *  embedding. Rerank is matched by keyword and never probed. */
const PROBE_ORDER: Array<"chat" | "embedding"> = ["chat", "embedding"];

/** Session cache of per-endpoint classification results (keyed by base URL)
 *  so re-opening the picker does not re-probe everything. Persisted across
 *  restarts through settings.modelKindCache. */
const classifyCache = new Map<string, Map<string, ModelKind>>();

/** `v1`-anchored base URL: keeps an existing `/v1` suffix instead of
 *  doubling it ("https://api.openai.com/v1" → same; "https://api.deepseek.com"
 *  → "https://api.deepseek.com/v1"). */
function v1Base(base: string): string {
	return base.endsWith("/v1") ? base : `${base}/v1`;
}

/** Query an OpenAI/Anthropic-compatible endpoint for its model ids, keeping
 *  any context window the response reports per model. */
export async function fetchModelIds(
	base: string,
	apiKey: string,
	apiFormat: ChatApiFormat,
): Promise<Array<{ id: string; contextWindow?: number }>> {
	const url = `${v1Base(base)}/models`;
	const headers: Record<string, string> = apiFormat === "anthropic"
		? { "x-api-key": apiKey, "anthropic-version": "2023-06-01" }
		: { Authorization: `Bearer ${apiKey}` };
	const resp = await raceTimeout(requestUrl({ url, method: "GET", headers, throw: false }));
	if (!resp || resp.status !== 200) {
		const status = resp?.status ?? 0;
		throw new Error(`${t("fetchFailed")} (HTTP ${status})`);
	}
	const data = (resp.json as { data?: unknown })?.data;
	if (!Array.isArray(data)) return [];
	const out: Array<{ id: string; contextWindow?: number }> = [];
	for (const entry of data) {
		if (typeof entry !== "object" || entry === null) continue;
		const id = (entry as { id?: unknown }).id;
		if (typeof id !== "string" || id.length === 0) continue;
		const ctx = contextOf(entry);
		out.push(ctx === undefined ? { id } : { id, contextWindow: ctx });
	}
	return out;
}

/** Per-request timeout for classification probes: a hanging probe (server
 *  keeps the connection open) must not stall the whole sweep. */
const PROBE_TIMEOUT_MS = 10_000;

/** Resolve `null` when `p` does not settle within the probe timeout. The
 *  underlying request keeps running but its result is ignored. */
function raceTimeout<T>(p: Promise<T>): Promise<T | null> {
	return Promise.race([
		p,
		new Promise<null>((resolve) => setTimeout(() => resolve(null), PROBE_TIMEOUT_MS)),
	]);
}

/** Probe one endpoint family with a minimal request; 200 means the model is
 *  served there. A transport failure or timeout is treated as "no", never a
 *  throw. */
async function probeKind(
	base: string,
	apiKey: string,
	model: string,
	kind: "chat" | "embedding",
): Promise<boolean> {
	const v1 = v1Base(base);
	const url = kind === "chat" ? `${v1}/chat/completions` : `${v1}/embeddings`;
	const body: unknown = kind === "chat"
		? { model, messages: [{ role: "user", content: "hi" }], max_tokens: 1 }
		: { model, input: "hi", encoding_format: "float" };
	try {
		const resp = await raceTimeout(requestUrl({
			url,
			method: "POST",
			headers: { Authorization: `Bearer ${apiKey}`, "Content-Type": "application/json" },
			body: JSON.stringify(body),
			throw: false,
		}));
		return (resp as { status?: number } | null)?.status === 200;
	} catch {
		return false;
	}
}

/** Probe a single model id against the endpoint (chat or embedding probe).
 *  Used by the guide's manual model-ID entry to validate before adding. */
export async function validateModelId(
	base: string,
	apiKey: string,
	apiFormat: ChatApiFormat,
	model: string,
	kind: "chat" | "embedding",
): Promise<boolean> {
	return probeKind(base, apiKey, model, kind);
}

/** Classify one model: keyword hint first (zero requests), then probe the
 *  chat and embedding endpoints with early exit on the first 200. */
async function classifyModel(
	base: string,
	apiKey: string,
	model: string,
): Promise<ModelKind> {
	const hinted = classifyById(model);
	if (hinted !== null) return hinted;
	for (const kind of PROBE_ORDER) {
		if (await probeKind(base, apiKey, model, kind)) return kind;
	}
	return "unknown";
}

/** Run `fn` over items with at most `limit` concurrent executions. */
async function runPool<T>(
	items: readonly T[],
	limit: number,
	fn: (item: T) => Promise<void>,
): Promise<void> {
	let i = 0;
	const workers = Array.from({ length: Math.max(1, Math.min(limit, items.length)) }, async () => {
		while (i < items.length) {
			const item = items[i++];
			await fn(item);
		}
	});
	await Promise.all(workers);
}

/**
 * Fetch the endpoint's models live and classify each: rerank/embedding ids
 * come from keywords (zero requests); everything else is probed against the
 * chat and embedding endpoints (chat first, early exit) and tagged "unknown"
 * when neither answers. Results are session-cached AND persisted to
 * settings.modelKindCache (keyed by base URL — no credentials) so a restart
 * does not re-probe the same endpoint.
 * @param plugin - used for the persisted cache.
 * @param onProgress - called as classification advances; `model` is the
 *   freshly classified entry of this step (for incremental list rendering).
 */
export async function fetchAvailableModels(
	plugin: SmartVaultPlugin,
	baseUrl: string,
	apiKey: string,
	apiFormat: ChatApiFormat,
	onProgress?: (done: number, total: number, model?: FetchedModel) => void,
): Promise<FetchedModel[]> {
	const base = (baseUrl || "").trim().replace(/\/+$/, "");
	if (!base) throw new Error(t("fetchNeedsBaseUrl"));
	const entries = await fetchModelIds(base, apiKey, apiFormat);
	if (entries.length === 0) return [];
	// Anthropic-format providers serve chat models only — skip the probes.
	if (apiFormat === "anthropic") {
		const models = entries.map((e) => ({ id: e.id, kind: "chat" as const, ...(e.contextWindow === undefined ? {} : { contextWindow: e.contextWindow }) }));
		models.forEach((m, i) => onProgress?.(i + 1, models.length, m));
		return models;
	}
	// Cache keyed by base URL only (the model directory of an endpoint does
	// not depend on the key, and keys must never be persisted).
	const cacheKey = base;
	let cache = classifyCache.get(cacheKey);
	if (!cache) {
		cache = new Map();
		classifyCache.set(cacheKey, cache);
		const saved = plugin.settings.modelKindCache?.[cacheKey];
		if (saved) {
			for (const [modelId, kind] of Object.entries(saved)) {
				cache.set(modelId, kind as ModelKind);
			}
		}
	}
	const results: FetchedModel[] = [];
	let done = 0;
	await runPool(entries, 4, async (e) => {
		let kind = cache!.get(e.id);
		if (!kind) {
			kind = await classifyModel(base, apiKey, e.id);
			cache!.set(e.id, kind);
		}
		const model: FetchedModel = {
			id: e.id,
			kind,
			...(e.contextWindow === undefined ? {} : { contextWindow: e.contextWindow }),
		};
		results.push(model);
		done++;
		onProgress?.(done, entries.length, model);
	});
	// Persist the updated classification for this endpoint. "unknown" is NOT
	// persisted — it usually means a rate-limited/transient probe failure,
	// and caching it would hide the model from every later fetch. Skipping
	// it makes the next fetch re-probe those models.
	const savedObj: Record<string, string> = {};
	for (const [modelId, kind] of cache) {
		if (kind === "unknown") continue;
		savedObj[modelId] = kind;
	}
	plugin.settings.modelKindCache = { ...(plugin.settings.modelKindCache ?? {}), [cacheKey]: savedObj };
	void plugin.saveSettings();
	return results;
}

/** The persisted model list for an endpoint (id + kind from the kind cache,
 *  no network) — used to show candidates instantly while a live refresh runs. */
function getCachedModels(plugin: SmartVaultPlugin, base: string): FetchedModel[] {
	const saved = plugin.settings.modelKindCache?.[base];
	if (!saved) return [];
	const out: FetchedModel[] = [];
	for (const [id, kind] of Object.entries(saved)) {
		out.push({ id, kind: kind as ModelKind });
	}
	return out;
}

/** Look up a model's context window in the built-in catalog by id — the
 *  fetch API only returns model ids, so catalog-known models (e.g.
 *  deepseek-v4-flash → 1M) keep their real capacity instead of the generic
 *  128k fallback. */
function catalogContextWindow(modelId: string): number | undefined {
	for (const entry of CHAT_CATALOG) {
		for (const m of entry.models) {
			if (m.id === modelId) return m.contextWindow;
		}
	}
	return undefined;
}

/** Default context window for models the catalog does not describe. */
const DEFAULT_CONTEXT_WINDOW = 128000;

/** Default per-category capacity: chat models get the generic 128k context
 *  window, embedding models a 8k max-input (bge-m3's standard limit). */
function defaultContextFor(kind: ChatModelKind): number {
	return kind === "embedding" ? 8192 : DEFAULT_CONTEXT_WINDOW;
}

/** Compact token-count spelling: 1000000 → "1M", 262144 → "256K". */
export function formatContext(tokens: number): string {
	if (tokens >= 1000000) {
		const m = tokens / 1000000;
		return `${Number.isInteger(m) ? m : m.toFixed(1)}M`;
	}
	if (tokens >= 1000) {
		const k = tokens / 1000;
		return `${Number.isInteger(k) ? k : k.toFixed(1)}K`;
	}
	return String(tokens);
}

/** Candidate-picker modal (checkbox list); adopts the checked ids. */
class FetchModelsModal extends Modal {
	private picked = new Set<string>();

	constructor(
		app: App,
		private models: FetchedModel[],
		private existing: ReadonlySet<string>,
		private onAdopt: (ids: string[]) => void,
	) {
		super(app);
		this.modalEl.addClass("semlink-fetch-modal");
	}

	/** Whether the modal is currently mounted (guards background refreshes). */
	private alive = false;
	private listEl: HTMLElement | null = null;
	private refreshingEl: HTMLElement | null = null;
	private errorEl: HTMLElement | null = null;
	private emptyEl: HTMLElement | null = null;
	private searchEl: HTMLInputElement | null = null;
	/** Lower-cased model-id filter ("" = show all). */
	private filter = "";
	/** model id → rendered row, for incremental updates. */
	private rows = new Map<string, HTMLElement>();

	onOpen() {
		this.alive = true;
		this.titleEl.setText(t("fetchTitle"));
		const { contentEl } = this;
		contentEl.empty();
		contentEl.createDiv({ cls: "semlink-fetch-desc", text: t("fetchDescription") });
		this.searchEl = contentEl.createEl("input", {
			cls: "semlink-fetch-search",
			attr: { type: "text", placeholder: t("fetchSearchPlaceholder") },
		});
		this.searchEl.addEventListener("input", () => {
			this.filter = (this.searchEl?.value ?? "").trim().toLowerCase();
			this.renderList();
		});
		this.refreshingEl = contentEl.createDiv({ cls: "semlink-fetch-refreshing" });
		this.refreshingEl.addClass("semlink-hidden");
		this.errorEl = contentEl.createDiv({ cls: "semlink-fetch-error" });
		this.errorEl.addClass("semlink-hidden");
		this.emptyEl = contentEl.createDiv({ cls: "semlink-fetch-empty" });
		this.emptyEl.addClass("semlink-hidden");
		this.listEl = contentEl.createDiv({ cls: "semlink-fetch-list" });
		this.renderList();
		new Setting(contentEl)
			.addButton((btn) => btn.setButtonText(t("cancel")).onClick(() => this.close()))
			.addButton((btn) =>
				btn
					.setButtonText(t("fetchAdopt"))
					.setClass("mod-cta")
					.onClick(() => {
						this.onAdopt([...this.picked]);
						this.close();
					})
			);
	}

	onClose() {
		this.alive = false;
		this.listEl = null;
		this.refreshingEl = null;
		this.errorEl = null;
		this.emptyEl = null;
		this.searchEl = null;
		this.rows.clear();
		this.contentEl.empty();
	}

	/** Show/hide the "refreshing live list" indicator — a progress bar with a
	 *  small done/total label underneath (167/422 etc.). */
	setRefreshing(on: boolean, done?: number, total?: number): void {
		if (!this.refreshingEl) return;
		this.refreshingEl.toggleClass("semlink-hidden", !on);
		if (!on) return;
		this.refreshingEl.empty();
		if (done !== undefined && total !== undefined && total > 0) {
			const pct = Math.min(100, Math.round((done / total) * 100));
			const bar = this.refreshingEl.createDiv({ cls: "semlink-fetch-progress" });
			bar.createDiv({
				cls: "semlink-fetch-progress-fill",
				attr: { style: `width: ${pct}%` },
			});
			const label = this.refreshingEl.createDiv({ cls: "semlink-fetch-progress-label" });
			label.setText(
				t("fetchRefreshing").replace("{done}", String(done)).replace("{total}", String(total)),
			);
		} else {
			this.refreshingEl.setText(t("fetchRefreshingShort"));
		}
	}

	/** Show a fetch/refresh failure inside the modal. */
	setError(message: string): void {
		if (!this.errorEl) return;
		this.setRefreshing(false);
		this.errorEl.setText(message);
		this.errorEl.removeClass("semlink-hidden");
	}

	/** Replace the candidate list with freshly fetched results, keeping the
	 *  user's checked selection (by model id) and the configured markers. */
	setModels(models: FetchedModel[]): void {
		if (!this.alive) return;
		this.models = models;
		this.renderList();
		if (this.errorEl) this.errorEl.addClass("semlink-hidden");
		this.setRefreshing(false);
	}

	/** Add one freshly classified model to the list, or update its row when
	 *  it already exists (from cache) — the list grows incrementally while
	 *  the live fetch is still running. Rows that do not match the current
	 *  filter are kept in the data but not rendered. */
	upsertModel(model: FetchedModel): void {
		if (!this.alive) return;
		const index = this.models.findIndex((m) => m.id === model.id);
		if (index >= 0) {
			this.models[index] = model;
		} else {
			this.models.push(model);
		}
		if (!this.matchesFilter(model)) return;
		const row = this.renderItem(model);
		const existing = this.rows.get(model.id);
		if (existing && existing.isConnected) {
			existing.replaceWith(row);
		} else if (this.listEl) {
			this.listEl.appendChild(row);
		}
		this.rows.set(model.id, row);
	}

	/** Whether a model passes the current search filter. */
	private matchesFilter(model: FetchedModel): boolean {
		return this.filter.length === 0 || model.id.toLowerCase().includes(this.filter);
	}

	/** Render one candidate row (checkbox + id + kind tag + ctx + ✓). */
	private renderItem(model: FetchedModel): HTMLElement {
		const label = document.createElement("label");
		label.className = "semlink-fetch-item";
		const cb = label.createEl("input", { attr: { type: "checkbox" } });
		// Nothing is pre-checked — the user picks exactly what to add.
		cb.checked = this.picked.has(model.id);
		cb.addEventListener("change", () => {
			if (cb.checked) this.picked.add(model.id);
			else this.picked.delete(model.id);
		});
		label.createSpan({ text: model.id });
		// Kind tag: the three probed categories get accent colors, the
		// id-hinted ones (speech/image/video/translation) a neutral pill.
		const kindCls = model.kind === "embedding"
			? "is-embedding"
			: model.kind === "chat"
				? "is-chat"
				: model.kind === "rerank"
					? "is-rerank"
					: null;
		if (model.kind !== "unknown") {
			label.createSpan({
				cls: `semlink-fetch-kind${kindCls ? ` ${kindCls}` : ""}`,
				// The kind key must go through t() — showing the raw key
				// would print "modelTagChat" etc.
				text: t(modelKindKey(model.kind)),
			});
		}
		// Show the context window when the endpoint or the catalog
		// reported one (e.g. "1M"), right-aligned, so adopting is an
		// informed choice.
		const ctx = model.contextWindow ?? catalogContextWindow(model.id);
		if (ctx !== undefined) {
			label.createSpan({ cls: "semlink-fetch-ctx", text: formatContext(ctx) });
		}
		if (this.existing.has(model.id)) {
			label.createSpan({ cls: "semlink-fetch-existing", text: "✓" });
		}
		return label;
	}

	/** Render the checkbox list from the current candidate set, filtered. */
	private renderList(): void {
		if (!this.listEl) return;
		this.listEl.empty();
		this.rows.clear();
		for (const model of this.models) {
			if (!this.matchesFilter(model)) continue;
			const row = this.renderItem(model);
			this.rows.set(model.id, row);
			this.listEl.appendChild(row);
		}
		// "No match" hint when the filter yields nothing. A merely-empty list
		// (e.g. mid-refresh) shows nothing — the head already carries the
		// refresh progress label.
		if (this.emptyEl) {
			const showNoMatch = this.rows.size === 0 && this.filter.length > 0;
			this.emptyEl.toggleClass("semlink-hidden", !showNoMatch);
			if (showNoMatch) this.emptyEl.setText(t("fetchNoMatch"));
		}
	}
}

/** Modal hosting the "Add provider" (catalog) or "Add a custom provider"
 *  create card. Closes on cancel or after a provider is created. */
export class AddProviderModal extends Modal {
	constructor(
		app: App,
		private plugin: SmartVaultPlugin,
		private kind: "catalog" | "custom",
		private onCreated: (provider: ModelProvider) => void,
	) {
		super(app);
		this.modalEl.addClass("semlink-add-provider-modal");
		// The modal lives outside the settings pane, but its inner forms
		// reuse the `.smart-vault-settings .semlink-*` styles — scoping the
		// modal itself with the same class makes those selectors match.
		this.modalEl.addClass("smart-vault-settings");
	}

	onOpen() {
		this.titleEl.setText(this.kind === "catalog" ? t("pickProvider") : t("customTitle"));
		const { contentEl } = this;
		contentEl.empty();
		const opts = {
			onCancel: () => this.close(),
			onCreated: (provider: ModelProvider) => {
				this.close();
				this.onCreated(provider);
			},
		};
		if (this.kind === "catalog") {
			renderProviderCatalogGrid(contentEl, this.plugin, opts);
		} else {
			renderCustomCard(contentEl, this.plugin, opts);
		}
	}

	onClose() {
		this.contentEl.empty();
	}
}

/** Delete-confirmation modal for a chat provider. */
class DeleteProviderModal extends Modal {
	constructor(
		app: App,
		private displayName: string,
		private onConfirm: () => void,
	) {
		super(app);
		this.modalEl.addClass("semlink-delete-modal");
	}

	onOpen() {
		this.titleEl.setText(t("deleteTitle").replace("{provider}", this.displayName));
		const { contentEl } = this;
		contentEl.empty();
		contentEl.createDiv({ cls: "semlink-delete-desc", text: t("deleteDescription") });
		new Setting(contentEl)
			.addButton((btn) => btn.setButtonText(t("cancel")).onClick(() => this.close()))
			.addButton((btn) =>
				btn
					.setButtonText(t("deleteConfirm"))
					.setWarning()
					.onClick(() => {
						this.close();
						this.onConfirm();
					})
			);
	}

	onClose() {
		this.contentEl.empty();
	}
}

// ──── Model list editor (shared by chat editors and create cards) ────

/** The model-category choices offered per model row. */
const MODEL_KINDS: readonly ChatModelKind[] = [
	"chat",
	"embedding",
	"rerank",
	"tts",
	"asr",
	"image",
	"video",
	"translate",
];

/** i18n key for a model-category label. */
function modelKindKey(kind: ChatModelKind): string {
	switch (kind) {
		case "embedding": return "modelTagEmbedding";
		case "rerank": return "modelTagRerank";
		case "tts": return "modelTagTts";
		case "asr": return "modelTagAsr";
		case "image": return "modelTagImage";
		case "video": return "modelTagVideo";
		case "translate": return "modelTagTranslate";
		default: return "modelTagChat";
	}
}

export interface ModelProbe {
	baseUrl: string;
	apiKey: string;
	apiFormat: ChatApiFormat;
}

interface ModelListOptions {
	app: App;
	/** Plugin for the persisted model-kind cache. */
	plugin: SmartVaultPlugin;
	/** Read the current model rows (may be replaced after each change). */
	getModels: () => ChatModel[];
	/** Persist a (possibly new) model list. */
	onChange: (models: ChatModel[]) => void;
	/** Current endpoint facts for the fetch action. */
	probe: () => ModelProbe;
	/** Kind given to newly added rows. Defaults to "chat"; embedding-provider
	 *  editors pass "embedding" so models added there are selectable in the
	 *  General tab's embedding-model dropdown right away. */
	defaultKind?: ChatModelKind;
	/** Called after a structural change (add/remove a row, adopt fetched
	 *  models) so the surrounding page can re-render — e.g. the General tab's
	 *  model dropdowns derive their options from these lists. */
	onStructuralChange?: () => void;
}

interface ModelListHandle {
	/** Re-evaluate the fetch button's disabled state (call after the probe
	 *  fields — baseUrl / apiKey — change in the surrounding editor). */
	updateProbeState: () => void;
}

/** Render the model rows of one chat provider with add/fetch/remove actions. */
function renderModelList(containerEl: HTMLElement, opts: ModelListOptions): ModelListHandle {
	const section = containerEl.createDiv({ cls: "semlink-model-list" });
	const headEl = section.createDiv({ cls: "semlink-model-list-head" });
	headEl.createSpan({ cls: "semlink-model-list-title", text: t("chatModels") });
	const countEl = headEl.createSpan({ cls: "semlink-model-list-count" });
	const fetchBtn = headEl.createEl("button", { cls: "semlink-link-btn", text: t("fetchModels") });
	const rowsEl = section.createDiv({ cls: "semlink-model-rows" });
	const errorEl = section.createDiv({ cls: "semlink-model-error" });
	errorEl.addClass("semlink-hidden");
	const addBtn = section.createEl("button", { cls: "semlink-add-model-btn", text: `＋ ${t("chatAddModel")}` });

	let fetching = false;

	const updateProbeState = () => {
		const { baseUrl, apiKey } = opts.probe();
		const base = baseUrl.trim();
		// A live interrogation needs both the base URL and the key.
		const ok = base.length > 0 && apiKey.trim().length > 0;
		(fetchBtn as HTMLButtonElement).disabled = !ok || fetching;
		fetchBtn.setAttr("title", ok ? "" : t("fetchNeedsBaseUrl"));
	};

	const rerender = () => {
		const models = opts.getModels();
		countEl.setText(`(${String(models.length)})`);
		rowsEl.empty();
		models.forEach((model, mi) => {
			const rowEl = rowsEl.createDiv({ cls: `semlink-model-row${model.enabled === false ? " is-disabled" : ""}` });
			// Drag handle (leftmost): the ONLY element that starts a drag.
			const grip = rowEl.createEl("button", {
				cls: "semlink-icon-btn semlink-model-grip",
				attr: { "aria-label": t("modelDrag"), title: t("modelDrag") },
			});
			setIcon(grip, "grip-vertical");
			// Enable/disable switch.
			const enabledBox = rowEl.createEl("input", {
				cls: "semlink-model-enabled",
				attr: { type: "checkbox", title: t("modelEnabled"), "aria-label": t("modelEnabled") },
			});
			enabledBox.checked = model.enabled !== false;
			enabledBox.addEventListener("change", () => {
				model.enabled = enabledBox.checked;
				rowEl.toggleClass("is-disabled", !enabledBox.checked);
				opts.onChange(models);
				opts.onStructuralChange?.();
			});
			// Model-category selector (嵌入/对话/重排序…).
			const kindSel = rowEl.createEl("select", { cls: "semlink-input semlink-model-kind" });
			for (const kind of MODEL_KINDS) {
				kindSel.createEl("option", { value: kind, text: t(modelKindKey(kind)) });
			}
			kindSel.value = model.kind ?? "chat";
			kindSel.addEventListener("change", () => {
				model.kind = kindSel.value as ChatModelKind;
				// Embedding models have a max-input limit, not a chat context
				// window — the placeholder follows the row's category.
				ctxInput.setAttr("placeholder", model.kind === "embedding"
					? t("embedMaxInput")
					: t("chatContextWindow"));
				opts.onChange(models);
				// The category feeds the General tab's embedding/chat model
				// dropdowns — re-render so a model re-tagged as 嵌入/对话 shows
				// up there immediately (this is the "mark as embedding" step).
				opts.onStructuralChange?.();
			});
			const idInput = rowEl.createEl("input", {
				cls: "semlink-input",
				attr: { placeholder: t("chatModelId") },
			});
			idInput.value = model.id;
			idInput.addEventListener("input", () => {
				model.id = idInput.value;
				opts.onChange(models);
			});
			const ctxInput = rowEl.createEl("input", {
				cls: "semlink-input semlink-input-ctx",
				attr: {
					placeholder: (model.kind ?? "chat") === "embedding"
						? t("embedMaxInput")
						: t("chatContextWindow"),
				},
			});
			ctxInput.value = model.contextWindow != null ? formatContextWindow(model.contextWindow) : "";
			ctxInput.addEventListener("input", () => {
				const n = parseContextWindow(ctxInput.value);
				if (n !== null) {
					model.contextWindow = n;
					opts.onChange(models);
				}
			});
			const rmBtn = rowEl.createEl("button", {
				cls: "semlink-icon-btn semlink-icon-btn-danger",
				attr: { "aria-label": `${t("chatDeleteModel")} ${mi + 1}` },
			});
			setIcon(rmBtn, "trash");
			rmBtn.addEventListener("click", () => {
				models.splice(mi, 1);
				opts.onChange(models);
				opts.onStructuralChange?.();
				rerender();
			});

			// ── Drag to reorder via the grip handle only. The grip itself is
			// draggable (a `button` child of a draggable row sometimes fails to
			// start a drag in some browsers); the row stays a drop target. ──
			grip.setAttr("draggable", "true");
			grip.addEventListener("dragstart", (e) => {
				rowEl.addClass("is-dragging");
				e.dataTransfer?.setData("text/plain", String(mi));
				if (e.dataTransfer) e.dataTransfer.effectAllowed = "move";
			});
			rowEl.addEventListener("dragend", () => {
				rowEl.removeClass("is-dragging");
				rowsEl.querySelectorAll(".is-drag-over").forEach((el) => el.removeClass("is-drag-over"));
			});
			rowEl.addEventListener("dragover", (e) => {
				e.preventDefault();
				if (e.dataTransfer) e.dataTransfer.dropEffect = "move";
				rowEl.addClass("is-drag-over");
			});
			rowEl.addEventListener("dragleave", () => {
				rowEl.removeClass("is-drag-over");
			});
			rowEl.addEventListener("drop", (e) => {
				e.preventDefault();
				e.stopPropagation();
				rowEl.removeClass("is-drag-over");
				const from = parseInt(e.dataTransfer?.getData("text/plain") ?? "-1", 10);
				if (isNaN(from) || from < 0 || from === mi) return;
				const arr = opts.getModels();
				if (from >= arr.length || mi >= arr.length) return;
				const [moved] = arr.splice(from, 1);
				// Insert "before the row that was at mi" — shifts down one.
				const insertAt = mi > from ? mi - 1 : mi;
				arr.splice(insertAt, 0, moved);
				opts.onChange(arr);
				opts.onStructuralChange?.();
				rerender();
			});
		});
		updateProbeState();
	};

	addBtn.addEventListener("click", () => {
		const kind = opts.defaultKind ?? "chat";
		opts.getModels().push({ id: "", contextWindow: defaultContextFor(kind), kind });
		opts.onChange(opts.getModels());
		opts.onStructuralChange?.();
		rerender();
	});

	fetchBtn.addEventListener("click", async () => {
		const { baseUrl, apiKey, apiFormat } = opts.probe();
		const base = baseUrl.trim().replace(/\/+$/, "");
		fetching = true;
		updateProbeState();
		errorEl.addClass("semlink-hidden");

		const current = opts.getModels();
		const known = new Set(current.map((m) => m.id).filter((id) => id.length > 0));
		/** Adopt the picked ids using the freshest candidate list known. */
		const adopt = (picked: string[], candidates: FetchedModel[]) => {
			const byId = new Map(opts.getModels().map((m) => [m.id, m]));
			for (const id of picked) {
				const found = candidates.find((fm) => fm.id === id);
				if (!found) continue;
				const existing = byId.get(id);
				// Refresh the kind + context window of models already in the
				// list too: the endpoint classification and the catalog are
				// more accurate than the generic defaults. Unknown keeps the
				// current kind; missing context keeps the existing value.
				const kind: ChatModelKind = found.kind !== "unknown"
					? found.kind
					: existing?.kind ?? "chat";
				const ctx = found.contextWindow
					?? catalogContextWindow(id)
					?? existing?.contextWindow
					?? defaultContextFor(kind);
				byId.set(id, existing
					? { ...existing, id, contextWindow: ctx, kind }
					: { id, contextWindow: ctx, kind });
			}
			opts.onChange([...byId.values()]);
			opts.onStructuralChange?.();
			rerender();
		};

		// Open the picker immediately: cached models show instantly (or an
		// empty list on first run), and the live fetch + classification
		// progress streams into the modal until the real list lands.
		const cached = getCachedModels(opts.plugin, base);
		let latest = cached;
		const modal = new FetchModelsModal(opts.app, cached, known, (picked) => {
			adopt(picked, latest.length > 0 ? latest : cached);
		});
		modal.open();
		modal.setRefreshing(true);

		try {
			const models = await fetchAvailableModels(
				opts.plugin,
				baseUrl,
				apiKey,
				apiFormat,
				(done, total, model) => {
					// Stream progress AND the model list incrementally into
					// the open modal — rows appear as they are classified.
					modal.setRefreshing(true, done, total);
					if (model) modal.upsertModel(model);
				},
			);
			latest = models;
			if (models.length > 0) {
				modal.setModels(models);
			} else {
				modal.setError(t("fetchEmpty"));
			}
		} catch (e) {
			// Keep whatever the user can still work with; surface the failure
			// inside the modal (which stays open for manual selection).
			modal.setError(e instanceof Error ? e.message : String(e));
		} finally {
			fetching = false;
			fetchBtn.setText(t("fetchModels"));
			updateProbeState();
		}
	});

	rerender();
	return { updateProbeState };
}

// ──── Provider rows ────

interface RowOptions {
	name: string;
	/** Optional kind marker — providers themselves are NOT distinguished as
	 *  embedding/chat; the distinction lives on the models inside each editor. */
	tag?: string;
	dot?: "configured" | "missing";
	badge?: string;
	/** Index in its provider list (for drag reordering). */
	index: number;
	onEdit: () => void;
	onDelete?: () => void;
	/** Reorder: move the provider from `from` to `to` (drag & drop). */
	onDrop: (from: number, to: number) => void;
}

/** Look up an inline SVG logo for a provider by display name. */
export function providerLogo(name: string): string | undefined {
	return PROVIDER_LOGOS[name.toLowerCase().replace(/[^a-z0-9]/g, "")];
}

/** Append the provider's brand logo to `target`, or a fallback circle with
 *  the name's initial when no brand logo is known (e.g. custom providers). */
export interface BrandLogo {
	svg?: string;
}

/** Single source of truth for brand iconography: the SVG for a provider or
 *  model-brand name — the official `-color.svg` variant when the lobe-icons
 *  package ships one, the plain mono mark otherwise. Every render site
 *  (settings rows, catalog grid, onboarding cards, model-brand mapping) must
 *  go through this so the same name always yields the same image. */
export function brandLogoOf(name: string): BrandLogo {
	const key = name.toLowerCase().replace(/[^a-z0-9]/g, "");
	return { svg: providerLogo(key) };
}

/** Safely mount a brand-logo SVG string into an element (checker-safe,
 *  no innerHTML assignment). */
export function setSvgIcon(el: HTMLElement, svg: string): void {
	el.empty();
	const root = new DOMParser().parseFromString(svg, "image/svg+xml").documentElement;
	if (root && root.tagName !== "parsererror") el.appendChild(root);
}

function appendProviderLogo(target: HTMLElement, name: string, logoCls: string): void {
	const logo = brandLogoOf(name).svg;
	if (logo) {
		const logoEl = target.createDiv({ cls: logoCls });
		setSvgIcon(logoEl, logo);
		return;
	}
	const initial = (name || "").trim().charAt(0).toUpperCase() || "?";
	target.createDiv({ cls: "semlink-provider-fallback", text: initial });
}

/** Create one provider row. The row is compact: logo + name + status +
 *  buttons (编辑 opens the provider-detail modal, 删除 removes it); the whole
 *  row is draggable to reorder. No inline expansion. */
function createProviderRow(listEl: HTMLElement, opts: RowOptions): HTMLElement {
	const row = listEl.createDiv({ cls: "semlink-provider-row" });
	const head = row.createDiv({ cls: "semlink-provider-row-head" });
	// Drag handle (leftmost): a plain icon (no button styling) showing the row
	// can be reordered, and an alternative drag source. The row itself stays
	// draggable too.
	const grip = head.createSpan({
		cls: "semlink-provider-grip",
		attr: { "aria-label": t("modelDrag"), title: t("modelDrag") },
	});
	setIcon(grip, "grip-vertical");
	const identity = head.createDiv({ cls: "semlink-provider-identity" });
	appendProviderLogo(identity, opts.name, "semlink-provider-logo");
	identity.createSpan({ cls: "semlink-provider-name", text: opts.name });
	if (opts.tag) identity.createSpan({ cls: "semlink-provider-tag", text: opts.tag });
	if (opts.dot) {
		identity.createSpan({
			cls: `semlink-provider-dot ${opts.dot === "configured" ? "is-configured" : "is-missing"}`,
			attr: {
				title: opts.dot === "configured" ? t("credentialConfigured") : t("credentialMissing"),
				"aria-label": opts.dot === "configured" ? t("credentialConfigured") : t("credentialMissing"),
			},
		});
	}
	if (opts.badge) identity.createSpan({ cls: "semlink-provider-badge", text: opts.badge });
	const actions = head.createDiv({ cls: "semlink-provider-actions" });
	actions.createEl("button", { cls: "semlink-btn", text: t("edit") })
		.addEventListener("click", (e) => {
			e.stopPropagation();
			opts.onEdit();
		});
	if (opts.onDelete) {
		const delBtn = actions.createEl("button", { cls: "semlink-btn semlink-btn-danger", text: t("remove") });
		delBtn.addEventListener("click", (e) => {
			e.stopPropagation();
			opts.onDelete!();
		});
	}

	// ── Drag to reorder (press and hold, then drag) ──
	row.setAttr("draggable", "true");
	// The grip is also a drag source: a `button` child of a draggable row
	// sometimes fails to start a drag in some browsers, so the handle gets
	// its own `draggable` like the model rows.
	grip.setAttr("draggable", "true");
	const onDragStart = (e: DragEvent) => {
		(row as HTMLElement).addClass("is-dragging");
		e.dataTransfer?.setData("text/plain", String(opts.index));
		if (e.dataTransfer) e.dataTransfer.effectAllowed = "move";
	};
	row.addEventListener("dragstart", onDragStart);
	grip.addEventListener("dragstart", onDragStart);
	row.addEventListener("dragend", () => {
		(row as HTMLElement).removeClass("is-dragging");
		listEl.querySelectorAll(".is-drag-over").forEach((el) => el.removeClass("is-drag-over"));
	});
	row.addEventListener("dragover", (e) => {
		e.preventDefault();
		if (e.dataTransfer) e.dataTransfer.dropEffect = "move";
		row.addClass("is-drag-over");
	});
	row.addEventListener("dragleave", () => {
		row.removeClass("is-drag-over");
	});
	row.addEventListener("drop", (e) => {
		e.preventDefault();
		e.stopPropagation();
		row.removeClass("is-drag-over");
		const from = parseInt(e.dataTransfer?.getData("text/plain") ?? "-1", 10);
		if (!isNaN(from) && from >= 0 && from !== opts.index) {
			opts.onDrop(from, opts.index);
		}
	});
	return row;
}

/** Modal hosting the full provider detail (name / base URL / protocol / key /
 *  model list). Reuses the same editor as the old inline expansion. */
class ProviderEditorModal extends Modal {
	constructor(
		app: App,
		private plugin: SmartVaultPlugin,
		private provider: ModelProvider,
		private refresh: () => void,
	) {
		super(app);
		this.modalEl.addClass("semlink-provider-editor-modal");
		// Reuse the `.smart-vault-settings .semlink-*` styles inside the modal.
		this.modalEl.addClass("smart-vault-settings");
	}

	onOpen() {
		this.titleEl.setText(t("editProvider"));
		const { contentEl } = this;
		contentEl.empty();
		renderProviderEditor(contentEl, this.plugin, this.provider, this.refresh, () => this.close());
	}

	onClose() {
		this.contentEl.empty();
	}
}

// ──── Editors ────

/** Editor for one provider (embedding and chat are not distinct provider
 *  kinds): 显示名称 → Base URL → API 协议 → API 密钥 → 模型列表. The model
 *  list is kind-tagged — embedding/chat/… models all live in the same list. */
function renderProviderEditor(
	slot: HTMLElement,
	plugin: SmartVaultPlugin,
	p: ModelProvider,
	refresh: () => void,
	close: () => void,
): void {
	// Draft copy: edits are staged on the draft and only written back (and
	// saved) when 确定 is clicked; 取消 discards them.
	const draft: ModelProvider = {
		...p,
		models: p.models.map((m) => ({ ...m })),
	};
	// The model list is rendered last; the probe-state refresh below needs a
	// handle, so it is assigned at the end and dereferenced lazily.
	let modelHandle: ModelListHandle | null = null;

	new Setting(slot)
		.setName(t("chatProviderName"))
		.addText((text) =>
			text
				.setValue(draft.name)
				.onChange((value) => {
					draft.name = value;
				})
		);

	new Setting(slot)
		.setName(t("chatBaseUrl"))
		.addText((text) =>
			text
				.setPlaceholder("https://api.siliconflow.cn")
				.setValue(draft.apiBase)
				.onChange((value) => {
					draft.apiBase = value;
					modelHandle?.updateProbeState();
				})
		);

	new Setting(slot)
		.setName(t("chatApiFormat"))
		.addDropdown((dropdown) =>
			dropdown
				.addOptions({
					"openai": t("chatFormatOpenAI"),
					"anthropic": t("chatFormatAnthropic"),
				})
				.setValue(draft.apiFormat ?? "openai")
				.onChange((value) => {
					draft.apiFormat = value as ChatApiFormat;
					modelHandle?.updateProbeState();
				})
		);

	new Setting(slot)
		.setName(t("apiKey"))
		.addText((text) =>
			text
				.setPlaceholder("sk-...")
				.setValue(draft.apiKey)
				.onChange((value) => {
					draft.apiKey = value;
					modelHandle?.updateProbeState();
				})
		)
		.then((setting) => {
			const input = setting.controlEl.querySelector("input") as HTMLInputElement | null;
			if (input) input.type = "password";
		});

	modelHandle = renderModelList(slot, {
		app: plugin.app,
		plugin,
		getModels: () => draft.models,
		onChange: (models) => {
			draft.models = models;
		},
		probe: () => ({ baseUrl: draft.apiBase, apiKey: draft.apiKey, apiFormat: draft.apiFormat ?? "openai" }),
	});

	// Footer: commit the staged draft on 确定, discard it on 取消.
	const footer = slot.createDiv({ cls: "semlink-editor-footer" });
	footer.createEl("button", { cls: "semlink-btn", text: t("cancel") })
		.addEventListener("click", close);
	footer.createEl("button", { cls: "semlink-btn semlink-btn-cta", text: t("confirm") })
		.addEventListener("click", async () => {
			Object.assign(p, draft);
			p.models = draft.models;
			// The list is now user-curated: the onboarding guide must stop
			// auto-refetching it (that would resurrect removed models).
			p.curated = true;
			await plugin.saveSettings();
			refresh();
			close();
		});
}

// ──── Create cards (add provider / add custom provider) ────

interface ChatProviderDraft {
	name: string;
	baseUrl: string;
	apiKey: string;
	apiFormat: ChatApiFormat;
	models: ChatModel[];
}

interface DraftEditorOptions {
	submitLabel: string;
	submitBusyLabel: string;
	onCancel: () => void;
	onCreated: (provider: ModelProvider) => void;
}

/** Field set shared by the catalog-add and custom-provider create cards. */
function renderDraftEditor(
	slot: HTMLElement,
	plugin: SmartVaultPlugin,
	draft: ChatProviderDraft,
	opts: DraftEditorOptions,
): void {
	const errorEl = slot.createDiv({ cls: "semlink-draft-error" });
	errorEl.addClass("semlink-hidden");
	let busy = false;
	// The model list is rendered last (after protocol + key); the probe-state
	// refresh above needs a handle, so it is assigned lazily.
	let modelHandle: ModelListHandle | null = null;

	new Setting(slot)
		.setName(t("chatProviderName"))
		.addText((text) =>
			text
				.setPlaceholder("My Gateway")
				.setValue(draft.name)
				.onChange((value) => {
					draft.name = value;
				})
		);

	new Setting(slot)
		.setName(t("chatBaseUrl"))
		.addText((text) =>
			text
				.setPlaceholder("https://api.example.com")
				.setValue(draft.baseUrl)
				.onChange((value) => {
					draft.baseUrl = value;
					modelHandle?.updateProbeState();
				})
		);

	new Setting(slot)
		.setName(t("chatApiFormat"))
		.addDropdown((dropdown) =>
			dropdown
				.addOptions({
					"openai": t("chatFormatOpenAI"),
					"anthropic": t("chatFormatAnthropic"),
				})
				.setValue(draft.apiFormat)
				.onChange((value) => {
					draft.apiFormat = value as ChatApiFormat;
					modelHandle?.updateProbeState();
				})
		);

	new Setting(slot)
		.setName(t("chatApiKey"))
		.addText((text) =>
			text
				.setPlaceholder("sk-...")
				.setValue(draft.apiKey)
				.onChange((value) => {
					draft.apiKey = value;
					modelHandle?.updateProbeState();
				})
		)
		.then((setting) => {
			const input = setting.controlEl.querySelector("input") as HTMLInputElement | null;
			if (input) input.type = "password";
		});

	modelHandle = renderModelList(slot, {
		app: plugin.app,
		plugin,
		getModels: () => draft.models,
		onChange: (models) => {
			draft.models = models;
		},
		probe: () => ({ baseUrl: draft.baseUrl, apiKey: draft.apiKey, apiFormat: draft.apiFormat }),
	});

	new Setting(slot)
		.addButton((btn) => btn.setButtonText(t("cancel")).onClick(() => opts.onCancel()))
		.addButton((btn) => {
			btn.setButtonText(opts.submitLabel).setClass("mod-cta").onClick(async () => {
				if (busy) return;
			errorEl.addClass("semlink-hidden");
			if (!draft.baseUrl.trim()) {
					errorEl.setText(t("customNeedsBaseUrl"));
					errorEl.removeClass("semlink-hidden");
					return;
				}
				if (draft.models.length === 0 || draft.models.some((m) => !m.id.trim())) {
					errorEl.setText(t("customNeedsModels"));
					errorEl.removeClass("semlink-hidden");
					return;
				}
				busy = true;
				btn.setButtonText(opts.submitBusyLabel).setDisabled(true);
				const provider: ModelProvider = {
					id: `provider-${Date.now()}`,
					name: draft.name.trim() || draft.baseUrl.trim(),
					apiBase: draft.baseUrl.trim(),
					apiKey: draft.apiKey,
					apiFormat: draft.apiFormat,
					models: draft.models.map((m) => ({ ...m })),
					// The user explicitly built this list — it is curated.
					curated: true,
				};
				plugin.settings.providers.push(provider);
				await plugin.saveSettings();
				opts.onCreated(provider);
			});
		});
}

/** Catalog entries pinned to the front of the picker grid with a star, in
 *  display order (first = leftmost). */
const FEATURED_PROVIDERS = ["OpenRouter", "SiliconFlow"];

/** Step 1 of "Add provider": a 3-column grid of catalog cards (logo + name).
 *  Clicking a card creates the provider pre-filled from that catalog entry
 *  (apiKey empty, models from the catalog) and hands it to onCreated, which
 *  closes this modal and opens the provider editor (step 2). */
function renderProviderCatalogGrid(
	containerEl: HTMLElement,
	plugin: SmartVaultPlugin,
	opts: { onCancel: () => void; onCreated: (provider: ModelProvider) => void },
): void {
	const grid = containerEl.createDiv({ cls: "semlink-add-provider-grid" });
	// Featured providers are pinned to the front in FEATURED_PROVIDERS order;
	// Array#sort is stable, so the rest keep their catalog order.
	const featuredRank = (name: string) => {
		const i = FEATURED_PROVIDERS.indexOf(name);
		return i === -1 ? FEATURED_PROVIDERS.length : i;
	};
	const ordered = [...CHAT_CATALOG].sort((a, b) => featuredRank(a.name) - featuredRank(b.name));
	for (const entry of ordered) {
		const card = grid.createDiv({ cls: "semlink-add-provider-card" });
		if (FEATURED_PROVIDERS.includes(entry.name)) {
			card.createSpan({ cls: "semlink-add-provider-star", text: "⭐" });
		}
		const logo = brandLogoOf(entry.name).svg;
		if (logo) {
			const logoEl = card.createDiv({ cls: "semlink-add-provider-card-logo" });
			setSvgIcon(logoEl, logo);
		} else {
			card.createDiv({ cls: "semlink-add-provider-card-fallback", text: entry.name.charAt(0).toUpperCase() });
		}
		card.createDiv({ cls: "semlink-add-provider-card-name", text: entry.name });
		card.addEventListener("click", async () => {
			const provider: ModelProvider = {
				id: `provider-${Date.now()}`,
				name: entry.name,
				apiBase: entry.baseUrl,
				apiKey: "",
				apiFormat: entry.apiFormat,
				...(entry.wirePath ? { wirePath: entry.wirePath } : {}),
				models: entry.models.map((m) => ({ ...m })),
			};
			plugin.settings.providers.push(provider);
			await plugin.saveSettings();
			opts.onCreated(provider);
		});
	}

	// Trailing "custom provider" chip: closes this catalog modal and opens the
	// custom-provider form in its place, reusing the same onCreated callback.
	const customCard = grid.createDiv({ cls: "semlink-add-provider-card semlink-add-provider-card-custom" });
	customCard.createDiv({ cls: "semlink-add-provider-card-fallback", text: "＋" });
	customCard.createDiv({ cls: "semlink-add-provider-card-name", text: t("customProvider") });
	customCard.addEventListener("click", () => {
		opts.onCancel();
		new AddProviderModal(plugin.app, plugin, "custom", opts.onCreated).open();
	});
}

/** "Add a custom provider" card: route id + full details. Rendered inside
 *  the AddProviderModal. */
function renderCustomCard(
	containerEl: HTMLElement,
	plugin: SmartVaultPlugin,
	opts: { onCancel: () => void; onCreated: (provider: ModelProvider) => void },
): void {
	const card = containerEl.createDiv({ cls: "semlink-add-card" });

	const draft: ChatProviderDraft = {
		name: "",
		baseUrl: "",
		apiKey: "",
		apiFormat: "openai",
		models: [],
	};

	const bodyEl = card.createDiv({ cls: "semlink-add-card-body" });
	renderDraftEditor(bodyEl, plugin, draft, {
		submitLabel: t("create"),
		submitBusyLabel: t("creating"),
		onCancel: opts.onCancel,
		onCreated: opts.onCreated,
	});
}

// ──── Main render ────

export function renderModelsTab(
	plugin: SmartVaultPlugin,
	containerEl: HTMLElement,
	state: ModelsTabState,
	refresh: () => void,
): void {
	new Setting(containerEl).setName(t("sectionModel")).setHeading();

	// One unified provider list — embedding and chat are not distinct
	// provider kinds; drag-reordering works across the whole list.
	const providers = plugin.settings.providers;

	/** Move the row at `from` to `to` and persist. */
	const handleDrop = (from: number, to: number): void => {
		if (from < 0 || from >= providers.length || to < 0 || to >= providers.length || from === to) return;
		const [moved] = providers.splice(from, 1);
		// After removing `from`, every index above it shifts down by one —
		// inserting "before the row that was at `to`" lands at to-1 downward.
		const insertAt = to > from ? to - 1 : to;
		providers.splice(insertAt, 0, moved);
		void plugin.saveSettings().then(() => refresh());
	};

	const listEl = containerEl.createDiv({ cls: "semlink-provider-rows" });

		for (let i = 0; i < providers.length; i++) {
			const p = providers[i];
			// Used by the delete handler below: if the deleted provider hosts
			// the active embedding model, clear that selection.
			const activePid = (plugin.settings.embeddingModelKey || "").split("::")[0];
			createProviderRow(listEl, {
				name: p.name,
				dot: p.apiKey ? "configured" : "missing",
				index: i,
			onEdit: () => {
				new ProviderEditorModal(plugin.app, plugin, p, refresh).open();
			},
			onDrop: handleDrop,
			onDelete: () => {
				new DeleteProviderModal(plugin.app, p.name, () => {
					plugin.settings.providers = plugin.settings.providers.filter(
						(x) => x.id !== p.id,
					);
					// If the removed provider hosted the active embedding
					// model, fall back to the first provider (the runtime
					// resolves a missing key to its default).
					if (activePid === p.id) {
						plugin.settings.embeddingModelKey = "";
					}
					void plugin.saveSettings().then(() => refresh());
				}).open();
			},
		});
	}

		// ── Add actions (open the create modal) ──
		const addBlock = containerEl.createDiv({ cls: "semlink-provider-add" });
		const actions = addBlock.createDiv({ cls: "semlink-provider-add-actions" });
		actions.createEl("button", { cls: "semlink-btn semlink-btn-cta", text: `＋ ${t("addProvider")}` })
			.addEventListener("click", () => {
				new AddProviderModal(plugin.app, plugin, "catalog", () => {
					// No second step: the picked provider is appended to the
					// list as a new row; edit it later via the row's 编辑 button.
					// The trailing "custom" chip inside the catalog grid opens
					// the custom-provider form and reuses this same callback.
					refresh();
				}).open();
			});
	}
